#include <iostream>
#include <string>

bool matches(const std::string &pattern, const std::string &word) {
    if (pattern.size() != word.size()) {
        return false;
    }
    for (std::size_t i = 0; i < word.size(); i++) {
        if (pattern[i] != '?' && pattern[i] != word[i]) {
            return false;
        }
    }
    return true;
}

int main() {
    std::string pattern, word;
    if (!(std::cin >> pattern)) {
        return 0;
    }
    bool any = false;
    while (std::cin >> word) {
        if (matches(pattern, word)) {
            std::cout << word << '\n';
            any = true;
        }
    }
    if (!any) {
        std::cout << "нет\n";
    }
    return 0;
}

